def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        # Use the built‑in ISO format that includes microseconds and tzinfo if present
        return value.isoformat()
    except AttributeError:
        # Fallback to string representation if isoformat is not available
        return str(value)

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict representation of the point
    """
    if value is None:
        return None

    # Try shapely-like attribute access
    try:
        x = value.x
        y = value.y
        # Support optional z
        z = getattr(value, 'z', None)
    except AttributeError:
        # Fallback: maybe a sequence or iterable of coordinates
        try:
            # Attempt to extract from .coords attribute (e.g., shapely Point)
            coords = list(value.coords)
            if not coords:
                raise ValueError
            x, y = coords[0][0], coords[0][1]
            z = coords[0][2] if len(coords[0]) > 2 else None
        except Exception:
            # Final fallback: treat as a 2 or 3-tuple directly
            try:
                if isinstance(value, (list, tuple)):
                    if len(value) >= 2:
                        x, y = value[0], value[1]
                        z = value[2] if len(value) > 2 else None
                    else:
                        raise ValueError
                else:
                    raise ValueError
            except Exception:
                raise TypeError(f"Unsupported point type: {type(value).__name__}")

    data = {'x': x, 'y': y}
    if z is not None:
        data['z'] = z
    return data

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(super().keys())

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    for idx, item in enumerate(self):
        if item == key:
            return idx
    raise ValueError(f"{key} not found")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Try to locate the underlying data container.
    data = getattr(self, "_data", None)
    if data is None:
        data = getattr(self, "data", None)
    if data is None:
        # No data attribute – nothing to return.
        return []

    # Helper to convert any iterable to a list of values.
    def _to_value_list(d):
        if isinstance(d, (list, tuple)):
            return list(d)
        if isinstance(d, dict):
            return list(d.values())
        try:
            return list(d)
        except TypeError:
            return []

    # If no keys specified, return all values.
    if not keys:
        return _to_value_list(data)

    # Otherwise, filter based on keys provided.
    result = []

    # Local copy of values for indexed lookup (for dicts).
    if isinstance(data, dict):
        _vals = list(data.values())
    else:
        _vals = None

    for k in keys:
        if isinstance(k, int):
            # Indexed lookup
            if isinstance(data, (list, tuple)):
                # Support negative indices
                try:
                    result.append(data[k])
                except IndexError as exc:
                    raise IndexError(f"Index {k} is out of bounds") from exc
            else:
                # When underlying data is a dict, use indexed position of its values.
                if _vals is None:
                    _vals = list(data.values())
                try:
                    result.append(_vals[k])
                except IndexError as exc:
                    raise IndexError(f"Index {k} is out of bounds") from exc
        else:
            # Key based lookup
            if isinstance(data, dict):
                if k in data:
                    result.append(data[k])
                else:
                    raise KeyError(f"Key {k!r} not found in record")
            else:
                # For non-dict records, try to find key in supporting mapping
                keys_list = getattr(self, "_keys", None)
                values_list = getattr(self, "_values", None)
                if keys_list is not None and values_list is not None:
                    if k in keys_list:
                        idx = keys_list.index(k)
                        result.append(values_list[idx])
                    else:
                        raise KeyError(f"Key {k!r} not found in record")
                else:
                    # Fall back to attribute lookup if possible
                    if hasattr(self, k):
                        result.append(getattr(self, k))
                    else:
                        raise KeyError(f"Key {k!r} not found in record")

    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Try both common naming conventions for hidden storage
    if hasattr(self, "_keys") and hasattr(self, "_values"):
        key_list = self._keys
        values = self._values
        get_item = lambda i: values[i]
    elif hasattr(self, "_fields") and hasattr(self, "__len__") and hasattr(self, "__getitem__"):
        # Fallback to namedtuple-like record
        key_list = self._fields
        values = self
        get_item = lambda i: self[i]
    else:
        raise AttributeError("Record object lacks expected internal structure")

    # If no keys requested, return all fields
    if not keys:
        return dict(zip(key_list, values))

    result = {}
    for k in keys:
        if isinstance(k, int):
            idx = k
            if idx < 0:
                idx += len(values)
            if idx < 0 or idx >= len(values):
                raise IndexError("Index out of bounds: %r" % k)
            result[key_list[idx]] = get_item(idx)
        else:
            # treat as field name
            if k in key_list:
                idx = key_list.index(k)
                result[k] = get_item(idx)
            else:
                result[k] = None
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """Appends a DISCARD message to the output queue."""
    # Ensure hooks are dictionaries
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}

    # Create the DISCARD message. The actual format depends on the
    # underlying protocol implementation; typically a tuple or dict is used
    # for internal queuing before serialization.
    # Here we assume a simple tuple format: ('DISCARD', qid, n).
    message = ('DISCARD', qid, n)

    # Append the message to the output queue. The queue attribute name may
    # vary between implementations; use the most common pattern.
    try:
        self._output_queue.append(message)  # type: ignore[attr-defined]
    except AttributeError:
        # Fallback if the attribute is named differently
        try:
            self._queue.append(message)  # type: ignore[attr-defined]
        except AttributeError:
            # If no queue exists, use a generic list on the instance
            if not hasattr(self, '_queue'):
                self._queue = []
            self._queue.append(message)

    # Return a Response object that will handle hydration/dehydration and
    # invoke any handlers passed in.
    return Response(
        self,
        dehydration_hooks=dehydration_hooks,
        hydration_hooks=hydration_hooks,
        **handlers
    )

def deprecated(message):
    def decorator(func):
        import warnings
        import functools

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)

        return wrapper

    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    import re
    return tuple(int(x) for x in re.findall(r'\d+', s))

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    import os, sys
    if not cmd:
        return cmd
    if sys.platform != "win32":
        return cmd

    first = cmd[0]
    new_cmd = list(cmd)

    # Handle shebang on Windows
    if os.path.isfile(first):
        try:
            with open(first, "r", encoding="utf-8", newline=None) as f:
                first_line = f.readline()
                if first_line.startswith("#!"):
                    shebang = first_line[2:].strip()
                    parts = shebang.split()
                    if parts:
                        interpreter = parts[0]
                        interpreter_args = parts[1:]
                        new_cmd = (
                            [interpreter]
                            + interpreter_args
                            + [first]
                            + list(cmd[1:])
                        )
        except (OSError, UnicodeDecodeError):
            pass

    # Quote arguments for Windows CreateProcess
    def _quote(arg: str) -> str:
        if not arg or any(c in arg for c in " \t\n\v\""):
            # Surround with double quotes and escape internal quotes/backslashes
            escaped = '"'
            backslashes = 0
            for ch in arg:
                if ch == "\\":
                    backslashes += 1
                    escaped += ch
                elif ch == '"':
                    escaped += "\\" * (backslashes * 2 + 1) + ch
                    backslashes = 0
                else:
                    escaped += ch
                    backslashes = 0
            escaped += "\\" * (backslashes * 2) + '"'
            return escaped
        return arg

    return tuple(_quote(a) for a in new_cmd)

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorator(func):
        if maxsize <= 0:
            return func
        cache = {}
        order = []  # list of keys, most recent at end

        def _make_key(args, kwargs, typed):
            key = args
            if kwargs:
                # sort kwargs to have deterministic order
                for k in sorted(kwargs):
                    key += (k, kwargs[k])
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                # Move to the end to show it was recently used
                order.remove(key)
                order.append(key)
                return cache[key]
            # Compute new value
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)
            # Enforce the cache size limit
            if len(cache) > maxsize:
                oldest = order.pop(0)
                if oldest in cache:
                    del cache[oldest]
            return result

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        freq = {}

        def make_key(args, kwargs):
            key = args
            if kwargs:
                # Sort kwargs to ensure consistent key order
                items = tuple(sorted(kwargs.items()))
                key = key + items
            if typed:
                key = tuple((type(arg), arg) for arg in key)
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                freq[key] += 1
                return cache[key]
            # Call the function to compute result
            result = func(*args, **kwargs)
            # Add to cache, evict if necessary
            if len(cache) >= maxsize:
                # Find key with lowest frequency
                min_freq = None
                key_to_remove = None
                for k, f in freq.items():
                    if min_freq is None or f < min_freq:
                        min_freq = f
                        key_to_remove = k
                if key_to_remove is not None:
                    del cache[key_to_remove]
                    del freq[key_to_remove]
            cache[key] = result
            freq[key] = 1
            return result

        return wrapper
    return decorator

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(method):
        def wrapper(*args, **kwargs):
            cache_key = key(method, *args, **kwargs)
            if lock:
                with lock:
                    if cache_key in cache:
                        return cache[cache_key]
            else:
                if cache_key in cache:
                    return cache[cache_key]
            result = method(*args, **kwargs)
            if lock:
                with lock:
                    cache[cache_key] = result
            else:
                cache[cache_key] = result
            return result
        wrapper.__name__ = method.__name__
        wrapper.__doc__ = method.__doc__
        wrapper.__dict__.update(method.__dict__)
        return wrapper
    return decorator

@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception into a readable string with a shortened traceback.
        """
        import traceback
        import os

        # Get the traceback object from the exception
        tb = getattr(e, "__traceback__", None)
        if tb is None:
            return f"{type(e).__name__}: {e}"

        # Extract frames and limit depth
        frames = traceback.extract_tb(tb)[:max_level]

        # Build the output list
        parts = ["Traceback (most recent call last):"]

        for frm in frames:
            # Shorten the file path
            if max_path_level > 0:
                parts_path = os.path.normpath(frm.filename).split(os.sep)
                if len(parts_path) > max_path_level:
                    filename = os.sep.join(parts_path[-max_path_level:])
                else:
                    filename = os.path.normpath(frm.filename)
            else:
                filename = os.path.normpath(frm.filename)

            parts.append(f'  File "{filename}", line {frm.lineno}, in {frm.name}')
            if frm.line:
                parts.append(f'    {frm.line.strip()}')

        # Append the exception type and message
        parts.append(f"{type(e).__name__}: {e}")

        return "\n".join(parts)

