@classmethod
def _reset_logging(cls):
    """Reset"""
    import logging
    root = logging.getLogger()
    for h in list(root.handlers):
        root.removeHandler(h)
        h.close()
    root.setLevel(logging.WARNING)

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Build graph of precedence constraints and indegree counts
    graph = {}
    indegree = {}
    for order in orderings:
        for i, a in enumerate(order):
            if a not in graph:
                graph[a] = set()
            indegree.setdefault(a, 0)
            for b in order[i+1:]:
                if b not in graph:
                    graph[b] = set()
                indegree.setdefault(b, 0)
                if b not in graph[a]:
                    graph[a].add(b)
                    indegree[b] += 1

    # Compute a deterministic key for each element: earliest (order index, position)
    keys = {}
    for j, order in enumerate(orderings):
        for k, elem in enumerate(order):
            t = (j, k)
            if elem not in keys or t < keys[elem]:
                keys[elem] = t

    # Topological sort using deterministic ordering based on keys
    result = []
    # Initialize list of nodes with zero indegree
    zero_nodes = [n for n, d in indegree.items() if d == 0]
    while zero_nodes:
        # Select node with smallest key
        best = zero_nodes[0]
        best_key = keys[best]
        for n in zero_nodes[1:]:
            nk = keys[n]
            if nk < best_key:
                best = n
                best_key = nk
        zero_nodes.remove(best)
        result.append(best)
        for m in graph[best]:
            indegree[m] -= 1
            if indegree[m] == 0:
                zero_nodes.append(m)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return a dictionary mapping attribute names to their descriptions.

    Keyword Arguments:
    all -- If True, include attributes from all base classes (excluding 'object'); otherwise only attributes
           defined directly on the class where this method is called.
    """
    results: dict[str, str] = {}
    # Determine which classes to inspect
    classes = [self.__class__] if not all else [
        cls for cls in self.__class__.mro() if cls is not object
    ]

    for cls in classes:
        for name, attr in cls.__dict__.items():
            # Skip private/internal attributes and methods
            if name.startswith("_"):
                continue
            if callable(attr):
                continue
            # Attempt to retrieve a description
            desc = getattr(attr, "description", None)
            if desc is None:
                desc = getattr(attr, "__doc__", "")
            if desc is None:
                desc = ""
            results[name] = desc
    return results

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    def _get_names(cls):
        return [
            k
            for k, v in cls.__dict__.items()
            if not k.startswith("_") and not callable(v)
        ]

    result = _get_names(self.__class__)
    if all:
        for base in self.__class__.__mro__[1:]:
            result.extend(_get_names(base))
    return sorted(set(result))

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        # Skip non-mapping items that are not interfaces or implements specs
        if isinstance(item, (tuple, list)) and not hasattr(item, "__implements__"):
            output.extend(item)
        else:
            output.append(item)
    return output

