def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.
    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional, for each point first its
    coordinate is converted to string (separated by *separator*), then each
    part of its value.
    """
    # Prepare output lines
    lines = []
    if header is not None:
        lines.append(str(header))

    # Determine how to iterate over points; support dict-like or arbitrary iterable
    try:
        points_iter = self.items()  # dict-style: (coord, value)
    except AttributeError:
        try:
            points_iter = iter(self)  # generic iterable
        except TypeError:
            raise TypeError("object is not iterable - cannot convert to CSV")

    for point in points_iter:
        # Support (coord, value) pair directly or single value
        if isinstance(point, tuple) and len(point) == 2:
            coord, value = point
        else:
            coord, value = point, None

        # Convert coordinate(s)
        if isinstance(coord, (str, bytes)):
            coord_parts = [str(coord)]
        else:
            try:
                coord_parts = [str(c) for c in coord]
            except TypeError:
                coord_parts = [str(coord)]

        # Convert value(s)
        if value is None:
            value_parts = []
        elif isinstance(value, (str, bytes)):
            value_parts = [str(value)]
        else:
            try:
                value_parts = [str(v) for v in value]
            except TypeError:
                value_parts = [str(value)]

        # Build line and add to output
        line_parts = coord_parts + value_parts
        lines.append(separator.join(line_parts))

    return "\n".join(lines)

def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Attempt to import the relevant classes; if they are not available
    # the checks will simply fail.
    try:
        from .fillrequest import FillRequest
    except Exception:
        FillRequest = None

    try:
        from .source import Source
    except Exception:
        Source = None

    # Helper to iterate over a container if it is a sequence
    def is_sequence(obj):
        return isinstance(obj, (list, tuple))

    # If it's a single element
    if FillRequest is not None and isinstance(seq, FillRequest):
        return True
    if Source is not None and isinstance(seq, Source):
        return False

    # If it's a container of requests
    if is_sequence(seq):
        # Reject if any element is a Source
        if Source is not None and any(isinstance(elem, Source) for elem in seq):
            return False
        # Accept if any element is a FillRequest
        if FillRequest is not None and any(isinstance(elem, FillRequest) for elem in seq):
            return True

    # Fallback: check if it's an object with a `.fill_request` attribute
    # (used by some external representation)
    if hasattr(seq, "fill_request") and isinstance(seq.fill_request, (str, int, float, bytes)):
        return True

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(getattr(obj, 'run'))

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    return (
        hasattr(obj, 'fill') and callable(getattr(obj, 'fill'))
        and hasattr(obj, 'compute') and callable(getattr(obj, 'compute'))
    )

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Regular expressions for AWS-like tag keys and values.
    # Keys and values must be 1-256 characters and may contain alphanumerics,
    # spaces, periods, hyphens, and underscores.
    KEY_REGEX = re.compile(r'^[A-Za-z0-9_.-]{1,256}$')
    VALUE_REGEX = re.compile(r'^[A-Za-z0-9_.-]{0,256}$')

    errors = []

    if not isinstance(labels, dict):
        raise ValidationError([{'labels': 'Expected a dictionary of labels'}])

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            key_str = key.decode() if isinstance(key, bytes) else key
            if not KEY_REGEX.match(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex"})

        # Validate value(s)
        if isinstance(value, (list, tuple)):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    errors.append({str(v): 'expected string or bytes-like object'})
                else:
                    v_str = v.decode() if isinstance(v, bytes) else v
                    if not VALUE_REGEX.match(v_str):
                        errors.append({v_str: f"Label value '{v_str}' does not match the regex"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                v_str = value.decode() if isinstance(value, bytes) else value
                if not VALUE_REGEX.match(v_str):
                    errors.append({v_str: f"Label value '{v_str}' does not match the regex"})

    if errors:
        raise ValidationError(errors)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # If the response is not a list, nothing to update
    if not isinstance(response, list):
        return last_applied_manifest

    # Ensure the manifest is a list
    if not isinstance(last_applied_manifest, list):
        last_applied_manifest = []

    for idx, resp_item in enumerate(response):
        # Extend the manifest list if it is shorter than response
        if idx >= len(last_applied_manifest) or last_applied_manifest[idx] is None:
            last_applied_manifest.append({} if isinstance(resp_item, dict) else resp_item)

        # If the response item is a dictionary, recursively update its fields
        if isinstance(resp_item, dict):
            if isinstance(observer_schema, dict):
                # The observer schema describes the fields for each list element
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[idx], observer_schema, resp_item
                )
            elif isinstance(observer_schema, list):
                # Some schemas may be expressed as a list of field descriptors
                for field_schema in observer_schema:
                    if isinstance(field_schema, dict):
                        update_last_applied_manifest_dict_from_resp(
                            last_applied_manifest[idx], field_schema, resp_item
                        )
        else:
            # If the response item is not a dict, use the value directly
            last_applied_manifest[idx] = resp_item

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    # Iterate over the observed fields defined by the schema
    for field, sub_schema in observer_schema.items():
        # The field must exist in the current level of the response
        if field not in response:
            raise KeyError(
                f"Observed field '{field}' is missing from the API response"
            )

        # If the sub_schema indicates a nested dictionary, recurse
        if isinstance(sub_schema, dict):
            # Ensure the field exists in the manifest as a dict
            if field not in last_applied_manifest or not isinstance(
                last_applied_manifest[field], dict
            ):
                last_applied_manifest[field] = {}

            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], sub_schema, response[field]
            )
        else:
            # Primitive or leaf value. Only initialize if not already present.
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response[field]

    # The function updates in place; nothing to return.

def formatmany(
        self,
        sql: AnyStr,
        many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
    ) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
        """Convert a list of in‑style parameter sets into out‑style."""
        # If no parameters supplied, return the original SQL and empty list
        try:
            iterator = iter(many_params)
        except TypeError:
            raise TypeError("many_params must be an iterable of mappings or sequences")
        out_sql: AnyStr | None = None
        out_params_list: List = []
        for params in iterator:
            # Use the single‑row format method (assumed to exist on this class)
            formatted_sql, out_params = self.format(sql, params)
            # Ensure that all rows use the same formatted SQL template
            if out_sql is None:
                out_sql = formatted_sql
            elif formatted_sql != out_sql:
                raise ValueError("inconsistent SQL across parameter sets")
            out_params_list.append(out_params)
        # If out_sql was never set (e.g. empty iterator), keep original sql
        if out_sql is None:
            out_sql = sql
        return out_sql, out_params_list.

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        # Prefer the library's built‑in validator if available.
        try:
            from ocfl.validation import validate_object
        except Exception:
            # If no validator is present, fall back to a very light check
            def validate_object(_):
                try:
                    import os
                    # Basic sanity check: path must exist and be a directory
                    if isinstance(_, str):
                        if not os.path.isdir(_):
                            return False
                        # Check for at least one file that typically exists
                        # in an OCFL object – a manifest file
                        return any(f.startswith('manifest-')
                                   for f in os.listdir(_))
                    else:
                        # Assume a pyfilesystem instance
                        return bool(_) and _.isdir('.') and any(f.startswith('manifest-')
                                                                 for f in _.listdir('.'))
                except Exception:
                    return False

        # Run the validator – it may raise exceptions on errors.
        try:
            result = validate_object(path)
            # If the validator returns a list/tuple, interpret emptiness
            if isinstance(result, (list, tuple)):
                # If there are errors, result may contain a flag
                # but we treat any non‑empty list as a failure for safety.
                return not result
            return bool(result)
        except Exception:
            return False

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to retrieve the log from common attribute names
    log = getattr(self, 'validation_log', None) or getattr(self, 'log', None) or []
    # Ensure we have an iterable
    if not isinstance(log, (list, tuple)):
        return ''
    lines = []
    for entry in log:
        if isinstance(entry, str):
            # simple string entry
            lines.append(f"{prefix}{entry}")
        elif isinstance(entry, (list, tuple)):
            # allow tuple like (level, message) or (msg, level)
            # try to format with level if possible
            try:
                level, msg = entry
                lines.append(f"{prefix}[{str(level).upper()}] {msg}")
            except Exception:
                # fallback for odd structures
                lines.append(f"{prefix}{str(entry)}")
        else:
            # fallback for any other type
            lines.append(f"{prefix}{str(entry)}")
    return "\n".join(lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalize digests_used to a set for fast lookup
    if not isinstance(digests_used, set):
        digests_used = set(digests_used)

    missing_files = []
    for fname, digest in manifest_files.items():
        # Accept both string digests and digest dicts that might contain a 'digest' key
        if isinstance(digest, dict):
            digest_val = digest.get('digest') or digest.get('value')
        else:
            digest_val = digest

        if digest_val not in digests_used:
            missing_files.append(fname)

    if missing_files:
        raise RuntimeError(
            f"Missing required digests for files: {', '.join(missing_files)}"
        )

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is a InventoryValidator instance
    if not isinstance(prior, self.__class__):
        raise TypeError("prior must be an InventoryValidator instance")

    # Retrieve the inventory objects from both validators
    try:
        inv_self = getattr(self, "inventory")
        inv_prior = getattr(prior, "inventory")
    except AttributeError as e:
        raise AttributeError("Both InventoryValidator instances must expose an 'inventory' attribute") from e

    # Basic sanity: the two inventories must refer to the same item (by id or key)
    # Use 'id' attribute if present, otherwise fallback to comparison by other
    # attributes that uniquely identify the inventory (like 'name', 'path', etc.).
    def _get_key(inv):
        if hasattr(inv, "id"):
            return inv.id
        # fall back to a tuple of unique keys if defined
        unique = getattr(inv, "__unique_keys__", None)
        if unique is not None:
            return tuple(getattr(inv, k, None) for k in unique)
        # otherwise use all attributes except those related to versioning
        return tuple(sorted(
            (k, getattr(inv, k)) for k in dir(inv)
            if not k.startswith("_") and k not in ("version", "created_at", "updated_at")
        ))

    try:
        key_self = _get_key(inv_self)
        key_prior = _get_key(inv_prior)
    except Exception as e:
        raise ValueError("Unable to determine a unique key for inventory comparison") from e

    if key_self != key_prior:
        raise ValueError("Current and prior inventories refer to different objects")

    # Determine version numbers
    def _get_version(inv):
        if hasattr(inv, "version"):
            v = inv.version
        elif hasattr(inv, "created_at"):
            # if version not present, use timestamp ordering
            v = getattr(inv, "created_at", None)
        else:
            raise AttributeError("Inventory object lacks a 'version' or 'created_at' attribute")
        if v is None:
            raise ValueError("Inventory version information is missing")
        return v

    try:
        self_version = _get_version(inv_self)
        prior_version = _get_version(inv_prior)
    except Exception as e:
        raise ValueError("Unable to retrieve version information from inventories") from e

    # Compare the version information. If numbers, ensure prior_version < self_version.
    # If timestamps, ensure prior < self.
    if isinstance(self_version, (int, float)) and isinstance(prior_version, (int, float)):
        if prior_version >= self_version:
            raise ValueError("Prior inventory must have an older version number than current")
    else:
        # Assume we can compare via < for timestamps or other non-numeric types
        if not (prior_version < self_version):
            raise ValueError("Prior inventory must be older (by timestamp or comparable ordering) than current")

    # Finally, perform a deep consistency check between attributes that should be identical across versions.
    # We skip version-related fields to allow evolution.
    ignore_attrs = {"version", "created_at", "updated_at", "_creation_time", "_update_time"}
    attrs = {k for k in dir(inv_self) if not k.startswith("_") and k not in ignore_attrs}
    for attr in attrs:
        val_self = getattr(inv_self, attr, None)
        val_prior = getattr(inv_prior, attr, None)
        if val_self != val_prior:
            raise ValueError(f"Attribute '{attr}' differs between current and prior inventory objects")

    return True  # Validation succeeded

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}
    for logical_path, ver_map in inventory.items():
        # Expect ver_map to be a mapping version -> list/set of files
        if isinstance(ver_map, dict):
            files = ver_map.get(version)
            if files:
                # Ensure the result is a set of files
                path_map[logical_path] = set(files)
    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    # Normalize manifest_files to a set for efficient lookups.
    if not hasattr(manifest_files, "__contains__"):
        raise ValueError("manifest_files must be an iterable of file names")
    manifest_set = set(manifest_files)

    # Helper to validate a single fixity entry (a dict).
    def _validate_entry(entry):
        if not isinstance(entry, dict):
            raise ValueError(f"Each fixity entry must be a dict, got {type(entry).__name__}")

        # Define the allowed keys for a fixity entry.
        allowed_keys = {"algorithm", "value", "target"}
        entry_keys = set(entry.keys())

        # Check for missing keys.
        missing = allowed_keys - entry_keys
        if missing:
            raise ValueError(f"Fixity entry missing keys: {sorted(missing)}")

        # Check for unexpected keys.
        unexpected = entry_keys - allowed_keys
        if unexpected:
            raise ValueError(f"Fixity entry contains unexpected keys: {sorted(unexpected)}")

        target = entry.get("target")
        # Ensure the target is present in the manifest.
        if target not in manifest_set:
            raise ValueError(f"Fixity entry references unknown file: '{target}'")

    # If multiple entries are provided as a list/tuple, validate each.
    if isinstance(fixity, (list, tuple)):
        if not fixity:
            raise ValueError("Fixity list/tuple is empty")
        for idx, entry in enumerate(fixity):
            try:
                _validate_entry(entry)
            except ValueError as exc:
                raise ValueError(f"Error in fixity entry {idx}: {exc}") from None
    else:
        # Validate a single entry.
        _validate_entry(fixity)

    return True

def add_asset(self, basename, file_path):
    extensions = ['tiff', 'jpg', 'png']
    root_dir = file_path.rsplit('.', 1)[0]
    mapping = {}
    for ext in extensions:
        key = f"{basename}.{ext}"
        mapping[key] = f"{root_dir}.{ext}"
    return mapping

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    # Map XML directory path to the package basename (the XML filename without extension)
    xml_dir_to_base = {}

    # First pass: identify XML files and build directory-to-basename mapping
    with zipfile.ZipFile(zip_path, 'r') as zf:
        for info in zf.infolist():
            if info.is_dir():
                continue
            file_path = info.filename
            base, ext = os.path.splitext(os.path.basename(file_path))
            if ext.lower() == ".xml":
                dir_path = os.path.dirname(file_path)
                xml_dir_to_base[dir_path] = base

        # If there are no XML files, return empty dict
        if not xml_dir_to_base:
            return {}

        # Second pass: assign every file to the corresponding package based on directory prefix
        packages = {}
        xml_dirs = list(xml_dir_to_base.keys())
        for info in zf.infolist():
            if info.is_dir():
                continue
            file_path = info.filename
            matched_base = None
            matched_len = -1
            for xml_dir in xml_dirs:
                # Handle root directory separately (xml_dir == '')
                if xml_dir == "":
                    # File must be directly under root (no '/')
                    if "/" not in file_path:
                        if len(xml_dir) > matched_len:
                            matched_base = xml_dir_to_base[xml_dir]
                            matched_len = len(xml_dir)
                else:
                    prefix = xml_dir + "/"
                    if file_path.startswith(prefix):
                        if len(xml_dir) > matched_len:
                            matched_base = xml_dir_to_base[xml_dir]
                            matched_len = len(xml_dir)
            if matched_base is not None:
                packages.setdefault(matched_base, []).append(file_path)

        return packages

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        matches = node.xpath(xpath)
        if matches:
            return matches[0]
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _format(v, level):
        indent_str = '  ' * level
        if hasattr(v, 'pretty') and callable(v.pretty):
            return v.pretty(level, debug)
        if isinstance(v, dict):
            items = [f"{indent_str}  {repr(k)}: {_format(val, level+1)}" for k, val in sorted(v.items())]
            return "{\n" + ",\n".join(items) + f"\n{indent_str}" + "}"
        if isinstance(v, (list, tuple, set)):
            open_sym = '[' if isinstance(v, list) else '(' if isinstance(v, tuple) else '{'
            close_sym = ']' if isinstance(v, list) else ')' if isinstance(v, tuple) else '}'
            items = [f"{indent_str}  {_format(item, level+1)}" for item in v]
            return f"{open_sym}\n" + ",\n".join(items) + f"\n{indent_str}{close_sym}"
        return repr(v)

    indent_str = '  ' * indent
    lines = []
    if debug:
        lines.append(f"{indent_str}{self.__class__.__name__} (id={id(self)})")
    if hasattr(self, "__dict__") and self.__dict__:
        for key in sorted(self.__dict__):
            val = self.__dict__[key]
            val_repr = _format(val, indent + 1)
            lines.append(f"{indent_str}  {key} = {val_repr}")
    else:
        lines.append(f"{indent_str}{repr(self)}")
    return "\n".join(lines)

def get_versions():
    """Get version information or return default if unable to do so."""
    import subprocess
    try:
        rev = subprocess.check_output(
            ['git', 'rev-parse', 'HEAD'],
            stderr=subprocess.DEVNULL
        ).decode('utf-8', errors='ignore').strip()
        tag = subprocess.check_output(
            ['git', 'describe', '--tags', '--always', '--dirty'],
            stderr=subprocess.DEVNULL
        ).decode('utf-8', errors='ignore').strip()
        return {"full-revisionid": rev, "version": tag}
    except Exception:
        return {"full-revisionid": "unknown", "version": "0.0.0"}

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return "." if "+" in pieces else "+"

_registry = {}

def register_vcs_handler(vcs, method=None):
    """
    Decorator to register a function as the handler for a specific VCS.

    Usage:
        @register_vcs_handler('git')
        def handle_git(...):
            ...
    """
    def decorator(func):
        _registry[vcs] = func
        return func

    if method is None:
        return decorator
    # If the decorator is used without @ but with the method argument.
    return decorator(method)

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    seen = set()
    num_objects = 0
    good_objects = 0

    def _validate(obj):
        nonlocal num_objects, good_objects
        oid = id(obj)
        if oid in seen:
            return
        seen.add(oid)
        num_objects += 1
        ok = True

        # Object level validation
        if validate_objects and hasattr(obj, "validate"):
            try:
                ok = bool(obj.validate())
            except Exception as exc:
                ok = False
                if show_warnings:
                    print(f"Warning: validation failed for {obj!r} ({exc!s})")

        # Digest check
        if ok and check_digests and hasattr(obj, "digest") and hasattr(obj, "calculate_digest"):
            try:
                if obj.calculate_digest() != obj.digest:
                    ok = False
                    if show_warnings:
                        print(f"Warning: digest mismatch for {obj!r}")
            except Exception as exc:
                ok = False
                if show_warnings:
                    print(f"Warning: digest check error for {obj!r} ({exc!s})")

        if ok:
            good_objects += 1

        # Recurse into possible children
        children = None
        if hasattr(obj, "children"):
            children = getattr(obj, "children")
        elif hasattr(obj, "sub_objects"):
            children = getattr(obj, "sub_objects")
        elif hasattr(obj, "items"):
            # Might be a mapping of sub-objects
            items = getattr(obj, "items")
            try:
                children = items()
            except Exception:
                pass
        if children and isinstance(children, (list, tuple, set)):
            for child in children:
                _validate(child)

    # Identify root objects to start from
    roots = getattr(self, "objects", None)
    if roots is None:
        roots = getattr(self, "root_objects", None)
    if roots is None:
        roots = getattr(self, "items", None)
    if roots is None:
        roots = []
    # Normalize to iterable
    if isinstance(roots, dict):
        roots = list(roots.values())
    if not isinstance(roots, (list, tuple, set)):
        roots = [roots]

    for root in roots:
        _validate(root)

    return num_objects, good_objects

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params by adding or normalizing bug ID information."""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # Normalise bug_ids into the format Bugzilla expects for the 'ids' parameter.
    if bug_ids:
        if isinstance(bug_ids, (list, tuple)):
            # Convert each ID to a string and join with commas.
            params["ids"] = ",".join(str(bid) for bid in bug_ids)
        else:
            # Assume a single ID or a pre‑formatted string.
            params["ids"] = str(bug_ids)

    # Commonly, an API key is also required.  If this instance stores it, add it.
    api_key = getattr(self, "api_key", None)
    if api_key:
        params.setdefault("api_key", api_key)

    return params

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        for option in action.option_strings:
            flags.append(option)
    return ' '.join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
        parsed[name] = namespace
        unknown_sets.append(set(unknown))

    if unknown_sets:
        # arguments that were not recognized by any subparser
        remaining = sorted(set.intersection(*unknown_sets))
    else:
        remaining = []

    return parsed, remaining

def deep_merge_nodes(nodes):
    """
    Merge a list of (key_node, value_node) tuples by deeply merging mapping values
    for duplicate keys. The last occurrence of a non-mapping value wins.
    """
    # Helper to determine if a node represents a YAML mapping
    def is_mapping(node):
        return getattr(node, "tag", None) == "tag:yaml.org,2002:map" and hasattr(node, "value") and isinstance(node.value, list)

    # Recursively merge two mapping nodes
    def merge_mapping(m1, m2):
        dict1 = {pair[0].value: (pair[0], pair[1]) for pair in m1.value}
        dict2 = {pair[0].value: (pair[0], pair[1]) for pair in m2.value}
        merged_pairs = []
        for key in dict1.keys() | dict2.keys():
            if key in dict1 and key in dict2:
                key_node, val1 = dict1[key]
                _, val2 = dict2[key]
                merged_val = merge_values(val1, val2)
                merged_pairs.append((key_node, merged_val))
            elif key in dict1:
                merged_pairs.append(dict1[key])
            else:
                merged_pairs.append(dict2[key])
        return type(m1)(tag=m1.tag, value=merged_pairs)

    # Merge two value nodes according to the rules
    def merge_values(v1, v2):
        if is_mapping(v1) and is_mapping(v2):
            return merge_mapping(v1, v2)
        return v2

    merged_dict = {}
    key_order = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = (key_node, value_node)
            key_order.append(key)
        else:
            _, existing_value = merged_dict[key]
            merged_value = merge_values(existing_value, value_node)
            merged_dict[key] = (merged_dict[key][0], merged_value)

    return [(merged_dict[k][0], merged_dict[k][1]) for k in key_order]

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument
    flags in a space-separated string.
    """
    # collect all option strings from the parser's actions
    flags = []
    for action in getattr(parser, '_actions', []):
        # action.option_strings is a list of flag strings for optional arguments
        if getattr(action, 'option_strings', None):
            flags.extend(action.option_strings)
    return ' '.join(flags)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str):
        trimmed = val.strip()
        # Common representations of None in string form
        return trimmed.lower() in {"none", "null", "nan", ""}
    return False

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if value is None:
        return None
    if not isinstance(value, str):
        value = str(value)
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    result = []
    seen = set()
    def _rec(c):
        for sub in c.__subclasses__():
            if sub not in seen:
                seen.add(sub)
                result.append(sub)
                _rec(sub)
    _rec(cls)
    return result)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must contain at least one symbol")
    char_to_value = {char: idx for idx, char in enumerate(alphabet)}
    value = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        digit = char_to_value[ch]
        value = value * base + digit
    return value

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    return re.sub(r"^[\'\"]|[\'\"]$", "", name)

def split(s, platform='this'):
    import shlex, sys
    # Resolve platform flag
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    else:
        try:
            platform = int(platform)
        except Exception:
            raise ValueError('platform must be "this", 0 (Windows) or 1 (POSIX)')
    if platform == 1:
        # POSIX-like splitting
        return shlex.split(s, posix=True)
    elif platform == 0:
        # Windows CMD-like splitting
        return shlex.split(s, posix=False)
    else:
        raise ValueError('Unsupported platform flag: %r' % platform)

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '-i', '--exclude-standard'],
            stderr=subprocess.STDOUT
        ).decode('utf-8')
    except subprocess.CalledProcessError:
        # If git command fails, return empty string
        return ''
    # Split output into lines, strip whitespace, filter out empty lines
    files = [line.strip() for line in output.splitlines() if line.strip()]
    # Sort the file list
    files.sort()
    # Join into comma-separated string
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = frequency.strip()
    if not freq_str:
        raise ValueError("Empty frequency string")
    if freq_str.lower() == "always":
        return None

    # Try to split into number and unit
    parts = freq_str.split()
    if len(parts) == 2:
        number_str, unit_str = parts
    else:
        # handle cases like "3weeks" or "3  weeks"
        import re
        match = re.fullmatch(r'(\d+(\.\d+)?)([a-zA-Z]+)', freq_str.replace(' ', ''))
        if not match:
            raise ValueError(f"Cannot parse frequency: '{frequency}'")
        number_str, _, unit_str = match.group(1,2,3)

    try:
        # Only integer values are accepted for simplicity
        number = int(float(number_str))
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{number_str}'")

    unit = unit_str.lower()
    if unit in ("day", "days"):
        return datetime.timedelta(days=number)
    if unit in ("week", "weeks"):
        return datetime.timedelta(weeks=number)
    if unit in ("hour", "hours"):
        return datetime.timedelta(hours=number)
    if unit in ("minute", "minutes"):
        return datetime.timedelta(minutes=number)
    if unit in ("second", "seconds"):
        return datetime.timedelta(seconds=number)
    if unit in ("month", "months"):
        # Approximate a month as 30 days
        return datetime.timedelta(days=number * 30)

    raise ValueError(f"Unrecognized time unit: '{unit_str}'")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if host is None:
        return False
    host = host.strip()
    # Quick check for common localhost identifiers
    if host.lower() in ("localhost", "127.0.0.1", "::1"):
        return True
    try:
        # Resolve host to all address families
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in addrinfo:
        address = sockaddr[0]
        # Check for IPv4 loopback
        if address == "127.0.0.1":
            return True
        # Check for IPv6 loopback (both forms)
        if address == "::1" or address == "0:0:0:0:0:0:0:1":
            return True
    return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.
    """
    transformed = []
    for frag in find_paths:
        # Assume a string containing a colon is already a pattern (e.g., "pp:root/somedir")
        if ':' in frag:
            transformed.append(frag)
        else:
            transformed.append(f'sh:**/*{frag}*/**')
    return transformed

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the final command list or string
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
        if args:
            if isinstance(args, (list, tuple)):
                cmd.extend(args)
            else:
                # treat args as string and split by whitespace
                cmd.extend(args.split())
    else:
        # commands is assumed to be a string
        cmd = commands
        if args:
            if isinstance(args, (list, tuple)):
                # join args into a string safely
                arg_str = " ".join(args)
            else:
                arg_str = args
            cmd = f"{cmd} {arg_str}"
    # Prepare subprocess parameters
    run_kwargs = {
        "cwd": cwd,
        "env": env,
        "text": True
    }
    if hide_stderr:
        run_kwargs["stderr"] = subprocess.DEVNULL
    if isinstance(commands, (list, tuple)):
        # Non-shell execution for list commands
        run_kwargs["shell"] = False
        run_kwargs["capture_output"] = True
    else:
        # Shell execution for string commands
        run_kwargs["shell"] = True
        run_kwargs["capture_output"] = True
    if verbose:
        print(f"Running command: {cmd}")
    proc = subprocess.run(cmd, **run_kwargs)
    return proc

