def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.safe_dump
    try:
        # Try to use the default_flow_style keyword if supported
        result = dumper(obj, default_flow_style=False)
    except TypeError:
