def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json
    import os
    import re

    configs = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except FileNotFoundError as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Configuration file not found: {filename}',
                args=(),
                exc_info=exc
            )
            log_records.append(record)
            continue
        except json.JSONDecodeError as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=exc.lineno or 0,
                msg=f'JSON parse error in {filename}: {exc.msg}',
                args=(),
                exc_info=exc
            )
            log_records.append(record)
            continue
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Unexpected error loading {filename}: {exc}',
                args=(),
                exc_info=exc
            )
            log_records.append(record)
            continue

        if resolve_env:
            def _replace_env(value):
                if isinstance(value, str):
                    # Replace ${VAR} with environment variable
                    def repl(match):
                        var_name = match.group(1)
                        return os.getenv(var_name, '')
                    return re.sub(r'\$\{([^}]+)\}', repl, value)
                elif isinstance(value, dict):
                    return {k: _replace_env(v) for k, v in value.items()}
                elif isinstance(value, list):
                    return [_replace_env(v) for v in value]
                else:
                    return value
            data = _replace_env(data)

        if overrides:
            # Basic shallow merge: override top-level keys
            if isinstance(overrides, dict):
                data.update(overrides)

        configs[filename] = data

    return configs, log_records

