def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    seq_type = type(seq)
    # If seq is already a sequence (has __len__) we can return it unchanged.
    if hasattr(seq, "__len__"):
        return seq, seq_type

    # Otherwise seq must be iterable; gather its items.
    if bufsize is not None:
        result = []
        for i, item in enumerate(seq):
            if i >= bufsize:
                break
            result.append(item)
    else:
        # If seq is a generator or iterator, exhaust it into a list.
        result = list(seq)
    return result, seq_type

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Get or compute the current scale
    if other is None:
        # Compute the scale if not cached or recompute requested
        if getattr(self, "_scale", None) is None or recompute:
            # Try to sum directly from the stored bin values
            if hasattr(self, "_values") and self._values is not None:
                try:
                    self._scale = sum(self._values)
                except TypeError:
                    # In case _values is an iterator
                    self._scale = sum(v for v in self._values)
            else:
                # Fallback to item pairs if available
                try:
                    self._scale = sum(v for _, v in self.items())
                except Exception:
                    raise RuntimeError("Could not compute histogram scale")
        return getattr(self, "_scale", 0.0)

    # Rescaling branch
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value, got %r" % other)

    # Ensure current scale is available
    current_scale = self.scale(recompute=recompute)
    if current_scale == 0:
        raise LenaValueError("cannot rescale histogram with scale zero")

    # Compute scale factor and adjust bin values
    factor = other / current_scale
    if hasattr(self, "_values") and self._values is not None:
        # Scale the stored values in place
        try:
            self._values = [v * factor for v in self._values]
        except TypeError:
            # If _values is a numpy array or other iterable
            try:
                self._values *= factor
            except Exception:
                # Fallback: rebuild list
                self._values = [v * factor for v in self._values]
    else:
        # If no direct accessor, attempt to rebuild via items
        try:
            new_items = [(k, v * factor) for k, v in self.items()]
            if hasattr(self, "_set_items"):
                self._set_items(new_items)
            else:
                # If no setter, replace all values in place
                self._values = [v * factor for _, v in new_items]
        except Exception:
            pass

    # Update the cached scale
    self._scale = other
    return self

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new scale requested
    if other is None:
        return getattr(self, "_scale", None)

    # Validate that the new scale is numeric
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value")

    # Current scale must be known and non‑zero
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale: graph has unknown or zero scale")

    # Compute the rescaling factor
    ratio = other / current_scale

    # Rescale the last coordinate (and its errors) in all data points
    fields = getattr(self, "fields", None)
    if fields and isinstance(fields, (list, tuple)):
        idx = len(fields) - 1
        data = getattr(self, "data", None)
        if data is not None:
            for point in data:
                if isinstance(point, dict):
                    if fields[idx] in point:
                        point[fields[idx]] *= ratio
                else:
                    if isinstance(point, list):
                        point[idx] *= ratio
                    elif hasattr(point, "__getitem__"):
                        # Tuple or similar
                        # Re‑build the point to preserve immutability
                        new_point = list(point)
                        new_point[idx] = new_point[idx] * ratio
                        point.__class__ = type(new_point)  # pragma: no cover
                        point[:] = new_point
        # Rescale errors if present
        errors = getattr(self, "errors", None)
        if errors is not None:
            for err_point in errors:
                if isinstance(err_point, dict):
                    if fields[idx] in err_point:
                        err_point[fields[idx]] *= ratio
                else:
                    if isinstance(err_point, list):
                        err_point[idx] *= ratio
                    elif hasattr(err_point, "__getitem__"):
                        new_err = list(err_point)
                        new_err[idx] = new_err[idx] * ratio
                        err_point.__class__ = type(new_err)  # pragma: no cover
                        err_point[:] = new_err

    # Update the stored scale
    self._scale = other
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph."""
    if make_value is None:
        def make_value(b): 
            return b.content if hasattr(b, "content") else b
    # Resolve coordinate getter
    coord_funcs = {
        "left":     lambda b: b.left   if hasattr(b, "left")   else (b.low  if hasattr(b, "low")   else None),
        "right":    lambda b: b.right  if hasattr(b, "right")  else (b.high if hasattr(b, "high")  else None),
        "middle":   lambda b: ((b.left + b.right) / 2
                               if hasattr(b, "left") and hasattr(b, "right")
                               else ((b.low + b.high) / 2) 
                               if hasattr(b, "low") and hasattr(b, "high") else None)
    }
    get_coord = coord_funcs.get(get_coordinate)
    if get_coord is None:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    # Determine scale
    if scale is True:
        scale_val = getattr(hist, "scale", None)
    else:
        scale_val = scale

    points = []
    # Iterate over bins; assume hist has iterable of bins
    for bin_ in hist:
        x_coord = get_coord(bin_)
        y_val = make_value(bin_)
        # If make_value returns a tuple or list, convert to list
        if isinstance(y_val, tuple) or isinstance(y_val, list):
            y_vals = list(y_val)
        else:
            y_vals = [y_val]
        # Ensure number of y values matches remaining field names
        if len(y_vals) + 1 != len(field_names):
            # Pad with None if mismatch
            y_vals += [None] * (len(field_names) - len(y_vals) - 1)
        point = (x_coord, *y_vals)
        points.append(point)
    return {"field_names": field_names, "points": points, "scale": scale_val}

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    Checks that `candidate` defines all attributes and methods required by
    `iface`.  For callable attributes the signatures are compared (ignoring
    the implicit ``self``/``cls`` when present).  If a mismatch is found the
    function raises a :class:`TypeError`, unless *tentative* is true, in
    which case ``False`` is returned.  On success ``True`` is returned.
    """
    import inspect

    # Convenience: if both are classes and inheritance actually suffices
    try:
        if inspect.isclass(iface) and inspect.isclass(candidate):
            if issubclass(candidate, iface):
                return True
    except Exception:
        # In case of non-standard types; fall back to attribute checks
        pass

    def _check_method(name, iface_attr, cand_attr):
        try:
            iface_sig = inspect.signature(iface_attr)
        except (ValueError, TypeError):
            # ignore attributes with no signature (e.g. properties)
            return True
        try:
            cand_sig = inspect.signature(cand_attr)
        except (ValueError, TypeError):
            # Candidate may be a built-in method; skip exact comparison
            return True

        # Drop implicit first parameter if it's "self" or "cls" for instance/static methods
        iface_params = list(iface_sig.parameters.values())
        cand_params = list(cand_sig.parameters.values())

        if iface_params and iface_params[0].name in ("self", "cls"):
            iface_params = iface_params[1:]
        if cand_params and cand_params[0].name in ("self", "cls"):
            cand_params = cand_params[1:]

        if len(iface_params) != len(cand_params):
            raise TypeError(
                f"Signature mismatch for method '{name}': expected {iface_sig} but got {cand_sig}"
            )
        for iparam, cparam in zip(iface_params, cand_params):
            if iparam.kind != cparam.kind:
                raise TypeError(
                    f"Parameter kind mismatch in method '{name}': {iparam.kind} vs {cparam.kind}"
                )
        return True

    try:
        # Get a list of members from iface (excluding private and special)
        iface_members = {
            name: attr
            for name, attr in vars(iface).items()
            if not name.startswith("_")
        }

        for name, iface_attr in iface_members.items():
            # Skip properties: the descriptor will provide value in candidate
            if isinstance(iface_attr, property):
                if not hasattr(candidate, name):
                    raise TypeError(
                        f"{candidate.__name__} missing property '{name}' required by {iface.__name__}"
                    )
                continue

            try:
                cand_attr = getattr(candidate, name)
            except AttributeError:
                # The attribute could be defined on base classes
                if not any(hasattr(base, name) for base in candidate.__mro__):
                    raise TypeError(
                        f"{candidate.__name__} missing attribute '{name}' required by {iface.__name__}"
                    )
                continue

            if callable(iface_attr):
                if not callable(cand_attr):
                    raise TypeError(
                        f"Attribute '{name}' of {candidate.__name__} is not callable but {iface.__name__} requires a callable"
                    )
                _check_method(name, iface_attr, cand_attr)
            else:
                # Non-callable attribute: just ensure it's present (type validation omitted)
                pass

        return True
    except Exception as exc:
        if tentative:
            return False
        raise

