def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to handle a doubly‑linked list implementation
    if hasattr(self, "head") and hasattr(self, "tail"):
        # The most recently used node is immediately after the head sentinel
        node = getattr(self.head, "next", None)
        if node is None or node is getattr(self, "tail", None):
            raise IndexError("popitem from an empty cache")
        # Unlink the node from the list
        self.head.next = node.next
        node.next.prev = self.head
        # Update dictionary reference if it exists
        if hasattr(self, "cache") and isinstance(self.cache, dict):
            self.cache.pop(node.key, None)
        # Decrement size counter if present
        if hasattr(self, "size"):
            self.size -= 1
        return node.key, node.val

    # Fallback to a dictionary‑based implementation
    if hasattr(self, "cache") and isinstance(self.cache, dict):
        try:
            key, value = self.cache.popitem()
        except KeyError:
            raise IndexError("popitem from an empty cache")
        if hasattr(self, "size"):
            self.size -= 1
        return key, value

    # If the cache itself is a plain dict
    if isinstance(self, dict):
        try:
            key, value = self.popitem()
        except KeyError:
            raise IndexError("popitem from an empty dict")
        return key, value

    raise TypeError("popitem requires 'cache' or linked‑list attributes")

