def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Try to extract JSON payload if present
    json_payload = {}
    try:
        json_payload = request.get_json(silent=True) or {}
    except Exception:
        json_payload = {}

    # Combine query parameters, form data, and JSON payload into a single dictionary
    combined = {}
    try:
        # For request.args and request.form, use to_dict if available
        combined.update(request.args.to_dict(flat=True))
    except Exception:
        try:
            for key, value in request.args.items():
                combined[key] = value
        except Exception:
            pass
    try:
        combined.update(request.form.to_dict(flat=True))
    except Exception:
        try:
            for key, value in request.form.items():
                combined[key] = value
        except Exception:
            pass
    combined.update(json_payload)

    # Check for public message
    if 'public' in combined or combined.get('type') == 'public':
        return True
    # Check for private message
    if 'private' in combined or combined.get('type') == 'private':
        return True
    # Check for legacy payload (often contains a key like 'message')
    if 'message' in combined:
        return True

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # The Matrix API endpoints are typically prefixed by "/_matrix".
    # Attempt to read the request path from common request objects.
    path = None
    try:
        # FastAPI/Starlette requests have a `url` property with a `path` attribute.
        if hasattr(request, "url"):
            path = getattr(request.url, "path", None)
    except Exception:
        pass

    if not path and hasattr(request, "path"):
        # Some frameworks expose the path directly on the request.
        path = getattr(request, "path", None)

    if not path:
        # As a last resort, try to read the path from the first segment of the raw URL.
        if hasattr(request, "raw_path"):
            try:
                path = request.raw_path.decode("utf-8")
            except Exception:
                pass

    # Ensure we have a string to work with
    if not isinstance(path, str):
        return False

    # Normalise leading slash in case missing
    if not path.startswith("/"):
        path = "/" + path

    return path.startswith("/_matrix")

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        import urllib.request
        req = urllib.request.Request(url, method="HEAD")
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get("Content-Type")
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not tag:
        return False
    # Optional length limit: 64 characters
    if len(tag) > 64:
        return False

    # Define allowed characters
    allowed = set("abcdefghijklmnopqrstuvwxyz0123456789-_" )
    prev_char = ""
    # The tag must start and end with an alphanumeric character
    if not ((tag[0] >= 'a' and tag[0] <= 'z') or (tag[0] >= '0' and tag[0] <= '9')):
        return False
    if not ((tag[-1] >= 'a' and tag[-1] <= 'z') or (tag[-1] >= '0' and tag[-1] <= '9')):
        return False

    for c in tag:
        if c not in allowed:
            return False
        # No two special characters ('-' or '_') in a row
        if (c == '-' or c == '_') and (prev_char == '-' or prev_char == '_'):
            return False
        prev_char = c

    return True

def xml_children_as_dict(node):
    """
    Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        key = child.tag
        value = child.text
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(value)
                result[key] = existing
            else:
                result[key] = [existing, value]
        else:
            result[key] = value
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    JSON = __import__("json")
    try:
        data = JSON.loads(document)
    except Exception:
        ET = __import__("xml.etree.ElementTree")
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        root = ET.fromstring(document)
        subject = root.findtext("xrd:Subject", namespaces=ns)
        aliases = [a.text for a in root.findall("xrd:Alias", namespaces=ns)]
        links = [
            {"rel": l.get("rel"), "type": l.get("type"), "href": l.get("href")}
            for l in root.findall("xrd:Link", namespaces=ns)
        ]
        data = {"subject": subject, "aliases": aliases, "links": links}
    return data

def retrieve_and_parse_diaspora_webfinger(handle):
    """Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        from urllib.request import urlopen, Request
        from urllib.parse import urlencode
        import json
    except Exception:
        return {}
    try:
        resource = f"acct:{handle}"
        domain = handle.split("@", 1)[-1]
        base_url = f"https://{domain}/.well-known/webfinger"
        params = urlencode({"resource": resource})
        url = f"{base_url}?{params}"
        req = Request(url, headers={"Accept": "application/json"})
        with urlopen(req, timeout=10) as resp:
            data = resp.read()
            return json.loads(data.decode("utf-8"))
    except Exception:
        return {}

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        # Use the requests library to send the request. We assume requests is already imported.
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            # Generic request for other HTTP methods
            response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as err:
        # Return None for status code on failure and the exception instance
        return (None, err)

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of names of INI files inside the provided directories that contain the specified option string.
    """
    osmod = __import__('os')
    result = []
    for base_dir in settings_dirs:
        for root, dirs, files in osmod.walk(base_dir):
            for filename in files:
                if filename.lower().endswith('.ini'):
                    filepath = osmod.path.join(root, filename)
                    try:
                        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                            content = f.read()
                        if spec_option in content:
                            result.append(filename)
                    except (OSError, IOError):
                        # Skip files that cannot be read
                        pass
    return sorted(result)

