@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        import yaml

        if spec_content is None:
            raise IRValidatorException("Spec content is None")

        # Load YAML content
        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML: {exc}")

        # Ensure we have a mapping
        if data is None:
            data = {}
        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must be a YAML mapping (dictionary).")

        # Define mandatory top‑level keys
        required_keys = {"name", "type", "inputs"}  # Modify according to your schema

        missing = required_keys - data.keys()
        if missing:
            missing_str = ", ".join(sorted(missing))
            raise IRValidatorException(f"Missing required fields in spec: {missing_str}")

        return data

