                try:
                    data = yaml.safe_load(f)
                except Exception as exc:
                    raise IRValidatorException(f"Failed to parse YAML: {exc}") from exc
        except FileNotFoundError as exc:
            raise IRValidatorException(f"YAML file not found: {yaml_file}") from exc
        except OSError as exc:
            raise IRValidatorException(f"Error reading YAML file: {exc}") from exc

        if data is None:
            raise IRValidatorException("YAML file is empty")

        # Determine mandatory keys if defined on the class
        mandatory_keys = getattr(cls, "_REQUIRED_KEYS", [])

        if not isinstance(mandatory_keys, (list, set, tuple)):
            raise ValueError("Class attribute _REQUIRED_KEYS must be a list/set/tuple of keys")

        missing_keys = [key for key in mandatory_keys if key not in data]
        if missing_keys:
            raise IRValidatorException(f"Missing required keys in YAML: {', '.join(missing_keys)}")

        return data
