def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Retrieve the command configuration
    try:
        command_cfg = self.commands[command_name]
    except (KeyError, AttributeError):
        raise KeyError(f"Command {command_name!r} not found")

    # Options may be stored under different keys; common ones are 'options' and 'args'
    options = None
    for key in ('options', 'args', 'parameters'):
        options = command_cfg.get(key) if isinstance(command_cfg, dict) else None
        if options:
            break

    if not isinstance(options, (dict, list)):
        raise KeyError(f"Command {command_name!r} has no option definitions")

    # If options is a list, look for a matching name
    if isinstance(options, list):
        for opt in options:
            if isinstance(opt, dict) and opt.get('name') == argument_name:
                return opt
        raise KeyError(f"Option {argument_name!r} not found for command {command_name!r}")

    # Otherwise assume a dict of option specs
    try:
        return options[argument_name]
    except KeyError:
        raise KeyError(f"Option {argument_name!r} not found for command {command_name!r}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # `self.allowed_lengths` should be a mapping of argument names to their maximum allowed lengths.
    for arg_name, arg_value in args.items():
        max_len = getattr(self, "allowed_lengths", {}).get(arg_name)
        if max_len is not None:
            # Convert value to string for length measurement (handles non-string types).
            val_len = len(str(arg_value))
            if val_len > max_len:
                raise ValueError(
                    f"Argument '{arg_name}' exceeds maximum length of {max_len} "
                    f"(got length {val_len})."
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Mapping of argument names to their valid choices (list/tuple/set or callable)
    choices = getattr(self, 'choices', {})

    # Normalize args to a dictionary of values
    if isinstance(args, dict):
        arg_values = args
    else:
        # Work with argparse.Namespace or similar objects
        arg_values = {k: getattr(args, k, None) for k in dir(args) if not k.startswith("_") and not callable(getattr(args, k, None))}

    # Validate each argument that has defined choices
    for name, allowed in choices.items():
        if name not in arg_values:
            continue  # argument not supplied; skip
        value = arg_values[name]
        if value is None:
            continue  # allow None (may be optional)

        # If allowed is a collection, check membership
        if isinstance(allowed, (list, tuple, set)):
            if value not in allowed:
                raise ValueError(f"Invalid value for argument '{name}': {value}. Allowed: {allowed}")
        else:
            # If allowed is not a simple collection, try a different approach
            try:
                # If it implements __contains__
                if hasattr(allowed, "__contains__") and value not in allowed:
                    raise ValueError(f"Invalid value for argument '{name}': {value}. Allowed: {allowed}")
            except Exception:
                # Fallback: assume callable (predicate) that returns a bool
                if callable(allowed) and not allowed(value):
                    raise ValueError(f"Invalid value for argument '{name}': {value}.")

    return args

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments. It can be a dictionary containing
            keys for the value and its bounds (min/minimum/min_value, max/maximum/max_value)
            or a tuple/list of the form (min, max, value).
        """
        # Extract min, max, and value from dict if possible
        if isinstance(args, dict):
            # Possible key names for value
            value_keys = ("value", "arg", "parameter")
            min_keys = ("min", "minimum", "min_value")
            max_keys = ("max", "maximum", "max_value")

            value = None
            min_val = None
            max_val = None

            for key in value_keys:
                if key in args:
                    value = args[key]
                    break

            for key in min_keys:
                if key in args:
                    min_val = args[key]
                    break

            for key in max_keys:
                if key in args:
                    max_val = args[key]
                    break
        # Extract from a sequence: (min, max, value)
        elif isinstance(args, (list, tuple)) and len(args) >= 3:
            min_val, max_val, value = args[0], args[1], args[2]
        else:
            # Unsupported format; nothing to validate
            return

        # If any essential component is missing, skip validation
        if value is None or min_val is None or max_val is None:
            return

        # Perform the comparison; raise if out of bounds
        try:
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument value ({value}) is out of bounds "
                    f"[{min_val}, {max_val}]"
                )
        except TypeError as exc:
            # If the values cannot be compared, re-raise with context
            raise TypeError(
                f"Cannot compare values {value!r}, {min_val!r}, and {max_val!r}"
            ) from exc
        return

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        # If no extra variables provided, simply return the original dictionary
        if not extra_vars:
            return vars_dict

        # Allow passing a dictionary directly as extra_vars
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # Iterate over the list of extra vars (expected in key=value format)
        for item in extra_vars:
            # Only process string items
            if not isinstance(item, str):
                continue

            # Split into key and value at the first '='
            if '=' in item:
                key, value = item.split('=', 1)
                # Try to interpret the value as a comma‑separated list
                if ',' in value:
                    value = [v.strip() for v in value.split(',')]
                else:
                    value = value.strip()
            else:
                # No explicit value, treat presence as a truthy flag
                key, value = item.strip(), True

            # Strip whitespace from key and set/override the entry
            vars_dict[key.strip()] = value

        return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in-place.
    By default, all values are left as strings.
    """
    # Retrieve the type mapping for the given parser.  The attribute
    # `_value_type_map` is expected to be a dict of the form:
    # {
    #     'parser_name': {
    #         'arg_name': <type>,   # e.g. int, float, bool, list, str
    #     },
    #     ...
    # }
    type_map = getattr(self, "_value_type_map", {}).get(parser_name, {})
    for key, val in list(values_dict.items()):
        if val is None:
            continue  # nothing to convert
        target_type = type_map.get(key)
        if not target_type:
            continue  # keep as string
        try:
            if target_type is bool:
                # Interpret common truthy strings
                values_dict[key] = val.lower() in ("true", "1", "yes", "y", "on")
            elif target_type is list:
                # Split comma‑separated string into a list
                values_dict[key] = [item.strip() for item in val.split(",")]
            else:
                values_dict[key] = target_type(val)
        except Exception:
            # If the conversion fails, leave the original value unchanged
            pass
    # The method mutates values_dict in-place and returns None.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key='', sep='.', result=None):
        if result is None:
            result = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key, sep=sep, result=result)
            else:
                result[new_key] = v
        return result

    plugin_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(plugin_file):
        return {}
    try:
        with open(plugin_file, 'r', encoding='utf-8') as f:
            spec = json.load(f)
    except (IOError, json.JSONDecodeError):
        return {}
    if isinstance(spec, dict):
        return _flatten(spec)
    return {}

